import org.apache.commons.cli.HelpFormatter;
import java.lang.reflect.Method;

public class Probe {
    public static void main(String[] args) throws Exception {
        HelpFormatter hf = new HelpFormatter();
        Method m = HelpFormatter.class.getDeclaredMethod("findWrapPos", String.class, int.class, int.class);
        m.setAccessible(true);
        try {
            Object r = m.invoke(hf, "abcdefghij", 4, 0);
            System.out.println("findWrapPos no-space result: " + r);
        } catch (Exception e) {
            System.out.println("findWrapPos no-space threw: " + e.getCause());
        }

        try {
            Object r = m.invoke(hf, "hello world", 8, 0);
            System.out.println("findWrapPos with-space result: " + r);
        } catch (Exception e) {
            System.out.println("findWrapPos with-space threw: " + e.getCause());
        }

        Method createPadding = HelpFormatter.class.getDeclaredMethod("createPadding", int.class);
        createPadding.setAccessible(true);
        try {
            Object r = createPadding.invoke(hf, -1);
            System.out.println("createPadding(-1) result: [" + r + "]");
        } catch (Exception e) {
            System.out.println("createPadding(-1) threw: " + e.getCause());
        }

        Method rtrim = HelpFormatter.class.getDeclaredMethod("rtrim", String.class);
        rtrim.setAccessible(true);
        System.out.println("rtrim(null) = " + rtrim.invoke(hf, (String) null));
        System.out.println("rtrim(\"\") = [" + rtrim.invoke(hf, "") + "]");
        System.out.println("rtrim(\"   \") = [" + rtrim.invoke(hf, "   ") + "]");
    }
}
